cd /workspace && cat > /tmp/build_fuzzer.sh << 'EOF'
#!/bin/bash
set -e
# Build lwan-request.c with FUZZING flag, but without the problematic missing headers
cd /workspace
# First, let's try to compile just the fuzzer source with the pre-built objects
# by creating a minimal build that avoids the missing headers conflicts
# Check if we can use -nostdinc to avoid the missing headers
# Actually, let's try a different approach: compile with -D_FORTIFY_SOURCE=0 and skip the missing headers
# Let's see what the request_fuzzer.cc includes
cat /workspace/repo-vul/src-vul/lwan/src/bin/fuzz/request_fuzzer.cc
EOF



bash /tmp/build_fuzzer.sh
#include <lwan.h>

extern "C" int fuzz_parse_http_request(const uint8_t *, size_t);

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
    return fuzz_parse_http_request(data, size);
}
